inline bool DebuffLoad( Debuff & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReader r( buffer, bytes, report != NULL ? report : &ignored );
    return DebuffLoadBody( r, value );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
static_assert( std::is_trivially_copyable<WeaponConfig>::value, "WeaponConfig must stay relocatable" );
static_assert( std::is_standard_layout<WeaponConfig>::value, "WeaponConfig must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<LoadoutConfig>::value, "LoadoutConfig must stay relocatable" );
static_assert( std::is_standard_layout<LoadoutConfig>::value, "LoadoutConfig must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<ProfileConfig>::value, "ProfileConfig must stay relocatable" );
static_assert( std::is_standard_layout<ProfileConfig>::value, "ProfileConfig must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RootConfig>::value, "RootConfig must stay relocatable" );
static_assert( std::is_standard_layout<RootConfig>::value, "RootConfig must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<Attachment>::value, "Attachment must stay relocatable" );
static_assert( std::is_standard_layout<Attachment>::value, "Attachment must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<Buff>::value, "Buff must stay relocatable" );
static_assert( std::is_standard_layout<Buff>::value, "Buff must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<Debuff>::value, "Debuff must stay relocatable" );
static_assert( std::is_standard_layout<Debuff>::value, "Debuff must stay standard-layout for offsetof" );

